[{"order":1,"type":"heading","text":"Next.js Data Fetching: getServerSideProps and getStaticProps"},{"order":2,"type":"subheading","text":"Introduction"},{"order":3,"type":"paragraph","text":"Next.js offers powerful data fetching capabilities that allow you to retrieve data at different stages of the application lifecycle. This tutorial will explore two primary data fetching methods: `getServerSideProps` and `getStaticProps`. Understanding these methods is crucial for building performant and SEO-friendly Next.js applications."},{"order":4,"type":"subheading","text":"Understanding Data Fetching Strategies"},{"order":5,"type":"paragraph","text":"Next.js provides different data fetching strategies to suit various use cases. The choice depends on how often the data changes and when you need to fetch it:"},{"order":6,"type":"bullet_point","text":"**Static Generation (SSG):** Data is fetched at build time and the page is pre-rendered as HTML. This is ideal for content that doesn't change frequently, such as blog posts or marketing pages. Uses `getStaticProps`."},{"order":7,"type":"bullet_point","text":"**Server-Side Rendering (SSR):** Data is fetched on each request, and the page is rendered on the server. This is suitable for dynamic content that needs to be up-to-date on every request, such as user dashboards or e-commerce product pages. Uses `getServerSideProps`."},{"order":8,"type":"subheading","text":"getStaticProps: Static Generation"},{"order":9,"type":"paragraph","text":"`getStaticProps` allows you to fetch data at build time. The data is then passed as props to your page component. This method is executed only on the server-side and never on the client-side."},{"order":10,"type":"paragraph","text":"Key characteristics of `getStaticProps`:"},{"order":11,"type":"bullet_point","text":"Runs only on the server-side."},{"order":12,"type":"bullet_point","text":"Data is fetched at build time."},{"order":13,"type":"bullet_point","text":"Ideal for static content that doesn't change often."},{"order":14,"type":"bullet_point","text":"Can be used with `getStaticPaths` for dynamic routes."},{"order":15,"type":"subheading","text":"Example: Fetching a List of Blog Posts"},{"order":16,"type":"paragraph","text":"Let's create a page that fetches a list of blog posts from a hypothetical API and displays them."},{"order":17,"type":"code","text":"import React from 'react';

function Blog({ posts }) {
  return (
    <ul>
      {posts.map((post) => (
        <li key={post.id}>{post.title}</li>
      ))}
    </ul>
  );
}

export async function getStaticProps() {
  const res = await fetch('https://your-api.com/posts');
  const posts = await res.json();

  return {
    props: {
      posts,
    },
  };
}

export default Blog;"},{"order":18,"type":"paragraph","text":"In this example:"},{"order":19,"type":"bullet_point","text":"We define a `Blog` component that receives the `posts` as props."},{"order":20,"type":"bullet_point","text":"`getStaticProps` fetches the blog posts from the API."},{"order":21,"type":"bullet_point","text":"The fetched `posts` are passed as props to the `Blog` component."},{"order":22,"type":"subheading","text":"getStaticPaths: Dynamic Routes with Static Generation"},{"order":23,"type":"paragraph","text":"When you have dynamic routes (e.g., `/posts/[id]`), you need to tell Next.js which paths should be pre-rendered at build time. This is where `getStaticPaths` comes in."},{"order":24,"type":"paragraph","text":"Key characteristics of `getStaticPaths`:"},{"order":25,"type":"bullet_point","text":"Defines which paths should be statically generated."},{"order":26,"type":"bullet_point","text":"Must be used in conjunction with `getStaticProps` for dynamic routes."},{"order":27,"type":"bullet_point","text":"Returns an object with `paths` and `fallback` properties."},{"order":28,"type":"subheading","text":"Example: Generating Paths for Blog Post IDs"},{"order":29,"type":"paragraph","text":"Let's create a page that displays a single blog post based on its ID. We'll use `getStaticPaths` to generate the paths for each blog post."},{"order":30,"type":"code","text":"import React from 'react';
import { useRouter } from 'next/router';

function Post({ post }) {
  const router = useRouter();

  if (router.isFallback) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h1>{post.title}</h1>
      <p>{post.content}</p>
    </div>
  );
}

export async function getStaticPaths() {
  const res = await fetch('https://your-api.com/posts');
  const posts = await res.json();

  const paths = posts.map((post) => ({
    params: { id: post.id.toString() },
  }));

  return {
    paths,
    fallback: false, // can also be true or 'blocking'
  };
}

export async function getStaticProps({ params }) {
  const res = await fetch(`https://your-api.com/posts/${params.id}`);
  const post = await res.json();

  return {
    props: {
      post,
    },
  };
}

export default Post;"},{"order":31,"type":"paragraph","text":"In this example:"},{"order":32,"type":"bullet_point","text":"`getStaticPaths` fetches all blog posts and creates an array of paths, each containing the `id` of a post."},{"order":33,"type":"bullet_point","text":"The `fallback` property is set to `false`, meaning that if a user tries to access a path that wasn't generated at build time, they'll see a 404 error. Setting it to `true` will attempt to generate the page on demand, and `'blocking'` will wait for the page to generate before rendering it."},{"order":34,"type":"bullet_point","text":"`getStaticProps` fetches the individual blog post based on the `id` passed in the `params` object."},{"order":35,"type":"subheading","text":"getServerSideProps: Server-Side Rendering"},{"order":36,"type":"paragraph","text":"`getServerSideProps` allows you to fetch data on each request. The data is then passed as props to your page component. This method is executed only on the server-side and never on the client-side."},{"order":37,"type":"paragraph","text":"Key characteristics of `getServerSideProps`:"},{"order":38,"type":"bullet_point","text":"Runs only on the server-side."},{"order":39,"type":"bullet_point","text":"Data is fetched on each request."},{"order":40,"type":"bullet_point","text":"Ideal for dynamic content that needs to be up-to-date on every request."},{"order":41,"type":"bullet_point","text":"Receives a `context` object containing request-specific information (e.g., cookies, headers)."},{"order":42,"type":"subheading","text":"Example: Fetching User Data on Each Request"},{"order":43,"type":"paragraph","text":"Let's create a page that fetches user data from an API on each request and displays it."},{"order":44,"type":"code","text":"import React from 'react';

function UserProfile({ user }) {
  return (
    <div>
      <h1>{user.name}</h1>
      <p>Email: {user.email}</p>
    </div>
  );
}

export async function getServerSideProps(context) {
  const res = await fetch('https://your-api.com/user');
  const user = await res.json();

  return {
    props: {
      user,
    },
  };
}

export default UserProfile;"},{"order":45,"type":"paragraph","text":"In this example:"},{"order":46,"type":"bullet_point","text":"We define a `UserProfile` component that receives the `user` as props."},{"order":47,"type":"bullet_point","text":"`getServerSideProps` fetches the user data from the API on each request."},{"order":48,"type":"bullet_point","text":"The fetched `user` is passed as props to the `UserProfile` component."},{"order":49,"type":"subheading","text":"When to Use Which Method"},{"order":50,"type":"paragraph","text":"Here's a guideline to help you choose between `getStaticProps` and `getServerSideProps`:"},{"order":51,"type":"bullet_point","text":"**Use `getStaticProps` when:**"},{"order":52,"type":"bullet_point","text":"The data is not user-specific."},{"order":53,"type":"bullet_point","text":"The data doesn't change frequently."},{"order":54,"type":"bullet_point","text":"You want the best possible performance and SEO."},{"order":55,"type":"bullet_point","text":"**Use `getServerSideProps` when:**"},{"order":56,"type":"bullet_point","text":"The data is user-specific."},{"order":57,"type":"bullet_point","text":"The data changes frequently."},{"order":58,"type":"bullet_point","text":"You need access to the request object (e.g., cookies, headers)."},{"order":59,"type":"subheading","text":"Conclusion"},{"order":60,"type":"paragraph","text":"`getServerSideProps` and `getStaticProps` are powerful tools for data fetching in Next.js. By understanding their characteristics and use cases, you can build performant and dynamic applications that meet your specific needs. Remember to choose the method that best suits the data requirements of your page to optimize performance and user experience."}]
